-- HAMRIQ people, performance, commissions, and payroll foundation.
create table if not exists public.recruiting_openings (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), title text not null, role_type text not null default 'sales', status text not null default 'open', description text not null default '', created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(company_id,id));
create table if not exists public.applicants (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), opening_id uuid, name text not null, phone text not null default '', email text not null default '', stage text not null default 'applied', resume_path text, notes text not null default '', created_at timestamptz not null default now(), unique(company_id,id), foreign key(company_id,opening_id) references public.recruiting_openings(company_id,id));
create table if not exists public.interview_events (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), applicant_id uuid not null, scheduled_at timestamptz, interviewer_id uuid, status text not null default 'scheduled', notes text not null default '', created_at timestamptz not null default now(), unique(company_id,id), foreign key(company_id,applicant_id) references public.applicants(company_id,id), foreign key(company_id,interviewer_id) references public.users(company_id,id));
create table if not exists public.sales_contests (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), name text not null, metric text not null, starts_on date not null, ends_on date not null, status text not null default 'planned', created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(company_id,id));
create table if not exists public.contest_results (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), contest_id uuid not null, user_id uuid not null, metric_value numeric not null default 0, rank integer, updated_at timestamptz not null default now(), unique(company_id,id), foreign key(company_id,contest_id) references public.sales_contests(company_id,id), foreign key(company_id,user_id) references public.users(company_id,id));
create table if not exists public.recognition_events (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), user_id uuid not null, category text not null, title text not null, details text not null default '', visibility text not null default 'team', awarded_by uuid, awarded_at timestamptz not null default now(), unique(company_id,id), foreign key(company_id,user_id) references public.users(company_id,id), foreign key(company_id,awarded_by) references public.users(company_id,id));
create table if not exists public.employee_reviews (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), user_id uuid not null, period_start date not null, period_end date not null, status text not null default 'draft', manager_notes text not null default '', employee_response text not null default '', acknowledged_at timestamptz, created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(company_id,id), foreign key(company_id,user_id) references public.users(company_id,id), foreign key(company_id,created_by) references public.users(company_id,id));
create table if not exists public.commission_rules (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), name text not null, rule_type text not null, applies_to_role text not null default 'rep', config jsonb not null default '{}'::jsonb, active boolean not null default true, created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(company_id,id));
create table if not exists public.commission_statements (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), user_id uuid not null, period_start date not null, period_end date not null, status text not null default 'projected', total_cents bigint not null default 0, details jsonb not null default '[]'::jsonb, approved_by uuid, approved_at timestamptz, paid_at timestamptz, unique(company_id,id), foreign key(company_id,user_id) references public.users(company_id,id), foreign key(company_id,approved_by) references public.users(company_id,id));
create table if not exists public.payroll_exports (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), provider text not null default 'external', period_start date not null, period_end date not null, status text not null default 'draft', export_payload jsonb not null default '{}'::jsonb, created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(company_id,id));
create table if not exists public.payroll_provider_connections (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), provider text not null, status text not null default 'not_connected', external_account_ref text, settings jsonb not null default '{}'::jsonb, connected_by uuid, updated_at timestamptz not null default now(), unique(company_id,id));

do $$ declare t text; begin foreach t in array array['recruiting_openings','applicants','interview_events','sales_contests','contest_results','recognition_events','employee_reviews','commission_rules','commission_statements','payroll_exports','payroll_provider_connections'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); execute format('grant select,insert,update on public.%I to authenticated',t); end loop; end $$;
create policy recruiting_mgr on public.recruiting_openings for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy applicants_mgr on public.applicants for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy interviews_mgr on public.interview_events for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy contests_read on public.sales_contests for select to authenticated using(private.company_access(company_id));
create policy contests_mgr on public.sales_contests for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy contest_results_read on public.contest_results for select to authenticated using(private.company_access(company_id));
create policy contest_results_mgr on public.contest_results for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy recognition_read on public.recognition_events for select to authenticated using(private.company_access(company_id) and (visibility in ('team','company') or user_id=(select auth.uid()) or private.is_manager(company_id)));
create policy recognition_mgr on public.recognition_events for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy reviews_read on public.employee_reviews for select to authenticated using(private.is_manager(company_id) or user_id=(select auth.uid()));
create policy reviews_mgr on public.employee_reviews for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy commission_rules_mgr on public.commission_rules for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy commission_statements_read on public.commission_statements for select to authenticated using(private.is_manager(company_id) or user_id=(select auth.uid()));
create policy commission_statements_mgr on public.commission_statements for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy payroll_exports_mgr on public.payroll_exports for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
create policy payroll_connections_mgr on public.payroll_provider_connections for all to authenticated using(private.is_manager(company_id)) with check(private.is_manager(company_id));
